import{_ as e,o as t,c as r,a3 as o}from"./chunks/framework.CJlOecQn.js";const p=JSON.parse('{"title":"Getting around: Metro, buses and taxis","description":"How to use the Doha Metro, Lusail Tram, Metrolink feeder buses, Karwa buses and Karwa taxis, and which apps and cards you need.","frontmatter":{"title":"Getting around: Metro, buses and taxis","description":"How to use the Doha Metro, Lusail Tram, Metrolink feeder buses, Karwa buses and Karwa taxis, and which apps and cards you need.","lastChecked":"2026-10","sourceCount":6},"headers":[],"relativePath":"guide/transport.md","filePath":"guide/transport.md"}'),s={name:"guide/transport.md"};function n(f,a,i,l,c,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="getting-around-metro-buses-and-taxis" tabindex="-1">Getting around: Metro, buses and taxis <a class="header-anchor" href="#getting-around-metro-buses-and-taxis" aria-label="Permalink to &quot;Getting around: Metro, buses and taxis&quot;">​</a></h1><p>Public transport in Qatar is built around the Doha Metro, with the Lusail Tram and feeder buses connecting to it. Mowasalat, the government-owned company behind the Karwa brand, runs the public buses and Karwa taxis.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup><sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></p><h2 id="doha-metro" tabindex="-1">Doha Metro <a class="header-anchor" href="#doha-metro" aria-label="Permalink to &quot;Doha Metro&quot;">​</a></h2><p>There are three lines, and all of them meet at Msheireb:<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></p><ul><li><strong>Red Line:</strong> from Al Wakra in the south to Lusail in the north. It also serves Hamad International Airport at Terminal 1.<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3]</a></sup></li><li><strong>Green Line:</strong> from Al Mansoura in the east to Al Riffa Mall of Qatar in the west.<sup class="footnote-ref"><a href="#fn3" id="fnref3:2">[3]</a></sup></li><li><strong>Gold Line:</strong> from Ras Bu Aboud to Al Aziziyah.<sup class="footnote-ref"><a href="#fn3" id="fnref3:3">[3]</a></sup></li></ul><p>There are two classes of travel: standard, which includes family carriages, and goldclub.<sup class="footnote-ref"><a href="#fn3" id="fnref3:4">[3]</a></sup></p><p>The metro runs from early until late, with a closure on Friday mornings for prayers. Hours change, so check the Doha Metro website or app before you rely on a late or early train.<sup class="footnote-ref"><a href="#fn3" id="fnref3:5">[3]</a></sup></p><h2 id="tickets-and-travel-cards" tabindex="-1">Tickets and Travel Cards <a class="header-anchor" href="#tickets-and-travel-cards" aria-label="Permalink to &quot;Tickets and Travel Cards&quot;">​</a></h2><p>Buy tickets from the vending machine at any station. A Travel Card is meant for frequent riders and is designed to be topped up.<sup class="footnote-ref"><a href="#fn3" id="fnref3:6">[3]</a></sup></p><p>The same travel card works on the Doha Metro, the Lusail Tram, Metrolink and metroexpress.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup> On the tram, tap in and tap out at the validators.<sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4]</a></sup></p><p>This page does not quote fares. Use the ticket options link on the Visit Qatar metro guide for current prices.<sup class="footnote-ref"><a href="#fn3" id="fnref3:7">[3]</a></sup></p><h2 id="lusail-tram" tabindex="-1">Lusail Tram <a class="header-anchor" href="#lusail-tram" aria-label="Permalink to &quot;Lusail Tram&quot;">​</a></h2><p>The tram connects to the metro at Lusail QNB and Legtaifiya stations.<sup class="footnote-ref"><a href="#fn4" id="fnref4:2">[4]</a></sup> Visit Qatar lists four lines and 25 stations.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><h2 id="metrolink-and-metroexpress" tabindex="-1">Metrolink and metroexpress <a class="header-anchor" href="#metrolink-and-metroexpress" aria-label="Permalink to &quot;Metrolink and metroexpress&quot;">​</a></h2><p>Metrolink is the feeder bus network that carries people to and from metro stations.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup> Visit Qatar describes the Metrolink bus as free.<sup class="footnote-ref"><a href="#fn3" id="fnref3:8">[3]</a></sup> Routes change, and Mowasalat added M307 and M308 between Al Sudan and Sports City stations from 10 May 2026, so check the Karwa Journey Planner app or call 4458 8888.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></p><p>In certain areas you can also request a free shared ride to the closest metro or tram station, booked on the Karwa app.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup> The Visit Qatar metro guide also lists a metroexpress ride share.<sup class="footnote-ref"><a href="#fn3" id="fnref3:9">[3]</a></sup></p><h2 id="karwa-buses" tabindex="-1">Karwa buses <a class="header-anchor" href="#karwa-buses" aria-label="Permalink to &quot;Karwa buses&quot;">​</a></h2><p>Karwa Bus is the public bus network, operated by Mowasalat.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup> The Karwa Bus app lets you plan a trip, see the network and manage your smart cards.<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5]</a></sup> Mowasalat also lists all public bus routes on its website.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></p><h2 id="taxis" tabindex="-1">Taxis <a class="header-anchor" href="#taxis" aria-label="Permalink to &quot;Taxis&quot;">​</a></h2><p>Karwa taxis are turquoise and easy to spot.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup></p><ul><li><strong>Booking:</strong> use the Karwa Taxi app, the website, or the 24 hour customer service centre on 4458 8888.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></li><li><strong>Cheaper option:</strong> the Economy Service, run with Fox Transport, is available only in the Karwa Taxi app.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></li><li><strong>Help:</strong> customer support runs 24 hours by phone, with WhatsApp as well.<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2]</a></sup></li><li><strong>Larger or private cars:</strong> Doha Limousine books through the Karwa app, online, or on the same number.<sup class="footnote-ref"><a href="#fn2" id="fnref2:4">[2]</a></sup></li></ul><p>Uber is also widely used.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup></p><h2 id="apps-to-install" tabindex="-1">Apps to install <a class="header-anchor" href="#apps-to-install" aria-label="Permalink to &quot;Apps to install&quot;">​</a></h2><ul><li><strong>Doha Metro app:</strong> for hours and service information.<sup class="footnote-ref"><a href="#fn3" id="fnref3:10">[3]</a></sup></li><li><strong>Karwa Taxi app:</strong> for taxis and the Economy Service.<sup class="footnote-ref"><a href="#fn2" id="fnref2:5">[2]</a></sup></li><li><strong>Karwa Bus app:</strong> for bus trips and smart cards.<sup class="footnote-ref"><a href="#fn5" id="fnref5:2">[5]</a></sup></li></ul><p>See also: <a href="./driving">Driving</a>, <a href="./arriving-and-visas">Arriving and visas</a>.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>Visit Qatar, <a href="https://visitqatar.com/intl-en/plan-your-trip/getting-around" target="_blank" rel="noreferrer">Getting around in Qatar</a>. Last checked: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn2" class="footnote-item"><p>Mowasalat (Karwa), <a href="https://www.mowasalat.com/our-service/taxi-limousine/" target="_blank" rel="noreferrer">Karwa Taxi &amp; Chauffeur Services</a>. Last checked: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref2:5" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn3" class="footnote-item"><p>Visit Qatar, <a href="https://visitqatar.com/intl-en/plan-your-trip/getting-around/doha-metro" target="_blank" rel="noreferrer">Doha Metro Guide: Tickets, Map &amp; Service Hours</a>. Last checked: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:2" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:3" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:6" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:7" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:8" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:9" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref3:10" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn4" class="footnote-item"><p>Ministry of Transport, <a href="https://mot.gov.qa/en/news/minister-transport-inaugurates-turquoise-line-lusail-tram-network" target="_blank" rel="noreferrer">Minister of Transport inaugurates the Turquoise Line of Lusail Tram network</a>. Last checked: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref4:2" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn5" class="footnote-item"><p>Mowasalat (Karwa), <a href="https://www.mowasalat.com/" target="_blank" rel="noreferrer">Mowasalat Qatar</a>. Last checked: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:1" class="footnote-backref" aria-label="Back to text">↑</a> <a href="#fnref5:2" class="footnote-backref" aria-label="Back to text">↑</a></p></li><li id="fn6" class="footnote-item"><p>Mowasalat (Karwa), <a href="https://www.mowasalat.com/mowasalat/public-transportation/" target="_blank" rel="noreferrer">Public Transportation</a>. Last checked: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="Back to text">↑</a></p></li></ol></section>',28)])])}const d=e(s,[["render",n]]);export{p as __pageData,d as default};
